import { SUPPORTED_FILE_TYPES } from '@beechcms/core'

/**
 * Sample attachment fixture object representation.
 */
export interface SampleFileAttachment {
  filename: string
  mimeType: string
  data: string
  buffer: Uint8Array
}

/**
 * Creates authentic binary or text sample buffers for all supported file types in BeechCMS.
 *
 * @param ext - The target file extension (e.g. 'jpg', 'pdf', 'zip').
 * @returns A Uint8Array containing valid, authentic format bytes.
 */
export function getSampleBufferForExtension(ext: string): Uint8Array {
  const normalised = ext.replace(/^\./, '').toLowerCase().trim()

  switch (normalised) {
    // --- IMAGES ---
    case 'png':
      return new Uint8Array([
        0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0x00, 0x00, 0x00, 0x0d,
        0x49, 0x48, 0x44, 0x52, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01,
        0x08, 0x06, 0x00, 0x00, 0x00, 0x1f, 0x15, 0xc4, 0x89, 0x00, 0x00, 0x00,
        0x0a, 0x49, 0x44, 0x41, 0x54, 0x78, 0x9c, 0x63, 0x00, 0x01, 0x00, 0x00,
        0x05, 0x00, 0x01, 0x0d, 0x0a, 0x2d, 0xb4, 0x00, 0x00, 0x00, 0x00, 0x49,
        0x45, 0x4e, 0x44, 0xae, 0x42, 0x60, 0x82,
      ])

    case 'jpg':
    case 'jpeg':
      return new Uint8Array([
        0xff, 0xd8, 0xff, 0xe0, 0x00, 0x10, 0x4a, 0x46, 0x49, 0x46, 0x00, 0x01,
        0x01, 0x01, 0x00, 0x48, 0x00, 0x48, 0x00, 0x00, 0xff, 0xdb, 0x00, 0x43,
        0x00, 0x08, 0x06, 0x06, 0x07, 0x06, 0x05, 0x08, 0x07, 0x07, 0x07, 0x09,
        0xff, 0xc0, 0x00, 0x0b, 0x08, 0x00, 0x01, 0x00, 0x01, 0x01, 0x01, 0x11,
        0x00, 0xff, 0xd9,
      ])

    case 'gif':
      return new Uint8Array([
        0x47, 0x49, 0x46, 0x38, 0x39, 0x61, 0x01, 0x00, 0x01, 0x00, 0x80, 0x00,
        0x00, 0x00, 0x00, 0x00, 0xff, 0xff, 0xff, 0x21, 0xf9, 0x04, 0x01, 0x00,
        0x00, 0x00, 0x00, 0x2c, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00,
        0x00, 0x02, 0x01, 0x44, 0x00, 0x3b,
      ])

    case 'webp':
      return new Uint8Array([
        0x52, 0x49, 0x46, 0x46, 0x1a, 0x00, 0x00, 0x00, 0x57, 0x45, 0x42, 0x50,
        0x56, 0x50, 0x38, 0x4c, 0x0d, 0x00, 0x00, 0x00, 0x2f, 0x00, 0x00, 0x00,
        0x10, 0x07, 0x10, 0x11, 0x11, 0x88, 0x88, 0xfe, 0x07, 0x00,
      ])

    case 'avif':
      return new Uint8Array([
        0x00, 0x00, 0x00, 0x1c, 0x66, 0x74, 0x79, 0x70, 0x61, 0x76, 0x69, 0x66,
        0x00, 0x00, 0x00, 0x00, 0x61, 0x76, 0x69, 0x66, 0x6d, 0x69, 0x66, 0x31,
        0x6d, 0x69, 0x61, 0x66,
      ])

    case 'bmp':
      return new Uint8Array([
        0x42, 0x4d, 0x3a, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x36, 0x00,
        0x00, 0x00, 0x28, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x00,
        0x00, 0x00, 0x01, 0x00, 0x18, 0x00, 0x00, 0x00, 0x00, 0x00, 0x04, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xff, 0xff, 0xff, 0x00,
      ])

    case 'ico':
      return new Uint8Array([
        0x00, 0x00, 0x01, 0x00, 0x01, 0x00, 0x01, 0x01, 0x00, 0x00, 0x01, 0x00,
        0x18, 0x00, 0x30, 0x00, 0x00, 0x00, 0x16, 0x00, 0x00, 0x00, 0x28, 0x00,
        0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x02, 0x00, 0x00, 0x00, 0x01, 0x00,
        0x18, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
      ])

    // --- DOCUMENTS ---
    case 'pdf':
      return new TextEncoder().encode(
        '%PDF-1.4\n1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj 2 0 obj<</Type/Pages/Count 1/Kids[3 0 R]>>endobj 3 0 obj<</Type/Page/MediaBox[0 0 3 3]>>endobj\nxref\n0 4\n0000000000 65535 f\n0000000009 00000 n\n0000000052 00000 n\n0000000095 00000 n\ntrailer<</Size 4/Root 1 0 R>>\nstartxref\n147\n%%EOF'
      )

    case 'docx':
    case 'xlsx':
    case 'pptx':
    case 'zip':
      return new Uint8Array([
        0x50, 0x4b, 0x03, 0x04, 0x0a, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x21, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x04, 0x00, 0x00, 0x00, 0x74, 0x65, 0x73, 0x74, 0x50, 0x4b, 0x01, 0x02,
        0x0a, 0x00, 0x0a, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x21, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x04, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x74, 0x65, 0x73, 0x74, 0x50, 0x4b, 0x05, 0x06,
        0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00, 0x32, 0x00, 0x00, 0x00,
        0x22, 0x00, 0x00, 0x00, 0x00, 0x00,
      ])

    case 'doc':
    case 'xls':
    case 'ppt':
      return new Uint8Array([
        0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x1a, 0xe1, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x3e, 0x00, 0x03, 0x00, 0xfe, 0xff, 0x09, 0x00, 0x06, 0x00, 0x00, 0x00,
      ])

    case 'txt':
      return new TextEncoder().encode('Hello BeechCMS! This is a valid UTF-8 text file sample.')

    case 'csv':
      return new TextEncoder().encode('id,name,value\n1,Alpha,100\n2,Beta,200\n3,Gamma,300')

    case 'md':
      return new TextEncoder().encode('# BeechCMS Sample Markdown\n\nContent for file testing.')

    // --- ARCHIVES & DATA ---
    case '7z':
      return new Uint8Array([
        0x37, 0x7a, 0xbc, 0xaf, 0x27, 0x1c, 0x00, 0x04, 0xe7, 0xd6, 0x40, 0x18,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
      ])

    case 'gz':
      return new Uint8Array([
        0x1f, 0x8b, 0x08, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x03, 0x73, 0x61,
        0x6d, 0x70, 0x6c, 0x65, 0x00, 0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
      ])

    case 'tar': {
      const tarBytes = new Uint8Array(512)
      // POSIX ustar at offset 257
      tarBytes[257] = 0x75
      tarBytes[258] = 0x73
      tarBytes[259] = 0x74
      tarBytes[260] = 0x61
      tarBytes[261] = 0x72
      return tarBytes
    }

    case 'json':
      return new TextEncoder().encode(JSON.stringify({ project: 'BeechCMS', version: '0.7.0', active: true }))

    default:
      throw new Error(`No sample fixture buffer defined for extension: ${ext}`)
  }
}

/**
 * Converts a Uint8Array buffer to a Base64 string for API multipart/json payload testing.
 */
export function bufferToBase64(bytes: Uint8Array): string {
  let binary = ''
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i])
  }
  return btoa(binary)
}

/**
 * Returns an attachment object for an extension using its authentic bytes and registered MIME.
 *
 * @param ext - The file extension.
 * @returns The structured SampleFileAttachment object.
 */
export function createSampleAttachment(ext: string): SampleFileAttachment {
  const normalised = ext.replace(/^\./, '').toLowerCase().trim()
  const def = SUPPORTED_FILE_TYPES[normalised]
  if (!def) {
    throw new Error(`Unsupported extension: ${ext}`)
  }
  const buffer = getSampleBufferForExtension(normalised)
  return {
    filename: `sample.${normalised}`,
    mimeType: def.primaryMime,
    data: bufferToBase64(buffer),
    buffer,
  }
}
